begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(22);
insert into fee_policies(version,effective_from,founder_only,fee_rate_bps,tax_rate_bps,stripe_fee_treatment,refund_treatment,rounding) select coalesce((select max(version) from fee_policies),0)+1,now()-interval '1 day',false,1000,0,'included','fee_retained','half_up' where not exists(select 1 from fee_policies where effective_from<=now() and (effective_until is null or effective_until>now()) and not founder_only);
insert into profiles(id,role,display_name) values('18000000-0000-0000-0000-000000000001','customer','Care owner'),('18000000-0000-0000-0000-000000000002','customer','Other owner');
insert into profiles(id,role,display_name,provider_status,license_verified,license_expires_at,insurance_verified,insurance_expires_at,service_categories,service_areas) select ('28000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,'provider','Care provider','approved',true,now()+interval '1 year',true,now()+interval '1 year',array['handyman'],array['Charlotte'] from generate_series(1,5) i;
insert into service_requests(id,customer_id,description,service_address,service_category,safety_status,workflow_status,intake_assessment_id,work_scope_snapshot,triage) select ('38000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,'18000000-0000-0000-0000-000000000001','Hinge adjustment','100 Care Lane','handyman','cleared','matched','care-assessment-'||i,'{"symptom":"hinge"}','{"urgency":"routine","hazards":[]}' from generate_series(1,5) i;
select set_config('request.jwt.claim.sub','18000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claim.role','authenticated',true);
select lives_ok($$select care_create_bundle(array['38000000-0000-0000-0000-000000000001','38000000-0000-0000-0000-000000000002']::uuid[])$$,'owned confirmed same-address tasks bundle');
select throws_ok($$select care_create_bundle(array['38000000-0000-0000-0000-000000000003','38000000-0000-0000-0000-000000000003']::uuid[])$$,'P0001','bundle requires 2 to 5 distinct requests','duplicate IDs rejected');
select is((select jsonb_array_length(scope_snapshot) from care_bundles limit 1),2,'bundle snapshots every task');
select throws_ok($$insert into quotes(request_id,provider_id,provider_name,scope,amount_cents) values('38000000-0000-0000-0000-000000000002','28000000-0000-0000-0000-000000000001','Provider','Secondary',10000)$$,'P0001','bundle_primary_request_required','secondary task cannot get separate quote');
select throws_ok($$insert into request_schedules(request_id,starts_at,time_zone,status) values('38000000-0000-0000-0000-000000000002',now()+interval '1 day','America/New_York','proposed')$$,'P0001','bundle_primary_request_required','secondary task cannot get separate visit');
select set_config('request.jwt.claim.sub','18000000-0000-0000-0000-000000000002',true);
select throws_ok($$select care_create_bundle(array['38000000-0000-0000-0000-000000000003','38000000-0000-0000-0000-000000000004']::uuid[])$$,'42501','bundle scope forbidden','other owner cannot bundle');
select set_config('request.jwt.claim.sub','18000000-0000-0000-0000-000000000001',true);
select throws_ok($$select care_apply_priority('38000000-0000-0000-0000-000000000003')$$,'42501','service role required','priority hook cannot be called by customers');
insert into quotes(id,request_id,provider_id,provider_name,scope,amount_cents,warranty_days) values('48000000-0000-0000-0000-000000000001','38000000-0000-0000-0000-000000000005','28000000-0000-0000-0000-000000000001','Provider','Hinge',10000,30);
insert into quote_snapshots(id,quote_id,request_id,provider_id,scope,amount_cents) values('58000000-0000-0000-0000-000000000001','48000000-0000-0000-0000-000000000001','38000000-0000-0000-0000-000000000005','28000000-0000-0000-0000-000000000001','Hinge',10000);
insert into quote_details(quote_id,request_id,diagnostic_cents,labor_cents,materials_cents,tax_cents,valid_until,site_visit_required,permit_required,inspection_status) values('48000000-0000-0000-0000-000000000001','38000000-0000-0000-0000-000000000005',0,10000,0,0,now()+interval '1 day',false,false,'not_required');
insert into jobs(request_id,accepted_quote_snapshot_id,deposit_cents) values('38000000-0000-0000-0000-000000000005','58000000-0000-0000-0000-000000000001',2000);
select is((select count(*) from care_dedicated),0::bigint,'no proposal before completion');
update jobs set work_status='completed',completed_at=now() where request_id='38000000-0000-0000-0000-000000000005';
select is((select status from care_dedicated where source_request_id='38000000-0000-0000-0000-000000000005'),'proposed','completion proposes without auto accepting');
select is((select warranty_until-completed_at from care_maintenance where request_id='38000000-0000-0000-0000-000000000005'),interval '30 days','accepted warranty derived from completed job');
select is((select count(*) from care_reminders where request_id='38000000-0000-0000-0000-000000000005'),1::bigint,'warranty reminder persisted');
select care_set_dedicated((select id from care_dedicated where source_request_id='38000000-0000-0000-0000-000000000005'),'accept');
select set_config('request.jwt.claim.role','service_role',true);
select care_apply_priority('38000000-0000-0000-0000-000000000003');
select is((select count(*) from request_matches where request_id='38000000-0000-0000-0000-000000000003'),1::bigint,'dedicated offer holds only one matching slot');
update care_priority set expires_at=now()-interval '1 second' where request_id='38000000-0000-0000-0000-000000000003';
update profiles set license_expires_at=now()-interval '1 second' where id='28000000-0000-0000-0000-000000000002';
select care_refresh_priority();
select is((select count(*) from request_matches where request_id='38000000-0000-0000-0000-000000000003'),3::bigint,'timeout fallback capped at three');
select is((select count(*) from request_matches where request_id='38000000-0000-0000-0000-000000000003' and provider_id='28000000-0000-0000-0000-000000000002'),0::bigint,'expired license excluded');
select is((select work_scope_snapshot->>'symptom' from service_requests where id='38000000-0000-0000-0000-000000000003'),'hinge','fallback keeps signed scope');
select set_config('request.jwt.claim.role','authenticated',true);
select throws_ok($$select care_record_maintenance('38000000-0000-0000-0000-000000000005','Hinge','[]')$$,'42501','completed provider required','customer cannot invent replaced parts');
select set_config('request.jwt.claim.sub','28000000-0000-0000-0000-000000000001',true);
select lives_ok($$select care_record_maintenance('38000000-0000-0000-0000-000000000005','Cabinet hinge','[{"name":"screw","quantity":2}]',now()+interval '1 year')$$,'completed provider records actual parts and reminder');
select is((select jsonb_array_length(scope_snapshot) from care_bundles limit 1),2,'bundle snapshots every task');
select throws_ok($$insert into quotes(request_id,provider_id,provider_name,scope,amount_cents) values('38000000-0000-0000-0000-000000000002','28000000-0000-0000-0000-000000000001','Provider','Secondary',10000)$$,'P0001','bundle_primary_request_required','secondary task cannot get separate quote');
select throws_ok($$insert into request_schedules(request_id,starts_at,time_zone,status) values('38000000-0000-0000-0000-000000000002',now()+interval '1 day','America/New_York','proposed')$$,'P0001','bundle_primary_request_required','secondary task cannot get separate visit');
select set_config('request.jwt.claim.sub','18000000-0000-0000-0000-000000000002',true);
set local role authenticated;
select is((select count(*) from care_maintenance),0::bigint,'RLS hides another customer maintenance');
select throws_ok($$insert into care_dedicated(customer_id,provider_id,source_request_id,service_address,category) values('18000000-0000-0000-0000-000000000002','28000000-0000-0000-0000-000000000001','38000000-0000-0000-0000-000000000005','address','handyman')$$,'42501','permission denied for table care_dedicated','direct proposal forgery denied');
reset role;
select * from finish();
rollback;
